private companion object {
        const val BRIDGE_NAME = "Yomi"
        const val TAB_LIBRARY = "library"

class ShellBridge(
    private val activity: Activity,
    private val serverUrlProvider: () -> String,
    private val pickTree: ActivityResultLauncher<Uri?>,
    private val online: OnlineModels,
    private val webUiInfo: () -> String,
    private val reloadUi: () -> Unit,
) {
    private val prefs get() = activity.getSharedPreferences("shell", Context.MODE_PRIVATE)

    // --- окружение -----------------------------------------------------------

    @JavascriptInterface
    fun baseUrl(): String = serverUrlProvider()

    @JavascriptInterface
    fun appVersion(): String =
        runCatching { activity.packageManager.getPackageInfo(activity.packageName, 0).versionName }
            .getOrNull() ?: "?"

    // --- веб-интерфейс ------------------------------------------------------

    /** Откуда взят интерфейс: из APK или переопределён `workspace/web`. */
    @JavascriptInterface
    fun webUi(): String = webUiInfo()

    /** Перечитать `workspace/web` и перезагрузить страницу. */
    @JavascriptInterface
    fun reloadUi() {
        activity.runOnUiThread { reloadUi() }
    }

    // --- настройки -----------------------------------------------------------

    @JavascriptInterface
    fun getPrefs(prefix: String): String {
        val out = JSONObject()
        prefs.all.forEach { (key, value) ->
            // Ключи провайдеров в веб не отдаются никогда — это и есть
            // содержимое приватных настроек приложения.
            if (key.startsWith("key.")) return@forEach
            if (prefix.isEmpty() || key.startsWith("$prefix.")) out.put(key, value)
        }
        return out.toString()
    }

