/**
     * Перечитать `workspace/web` и перезагрузить страницу. Кнопка в
     * настройках веб-слоя: правка интерфейса не должна требовать перезапуска
     * приложения. Перезагрузка идёт после пересканирования, иначе страница
     * забрала бы ещё старые файлы.
     */
    private fun reloadUi() {
        val tab = currentTab
        web.refreshAsync { changed ->
            webView.post {
                if (tab == currentTab && tab != TAB_BROWSER) openTab(tab)
                if (changed && tab != TAB_BROWSER) tellWeb("'ui:assets-changed'")
            }
        }
    }

input.oldString:
/**
     * Перечитать `workspace/web` и перезагрузить страницу. Кнопка в
     * настройках веб-слоя: правка интерфейса не должна требовать перезапуска
     * приложения.
     */
    private fun reloadUi() {
        web.refreshAsync { changed ->
            if (changed && currentTab != TAB_BROWSER) tellWeb("'ui:assets-changed'")
        }
        if (currentTab != TAB_BROWSER) openTab(currentTab)
    }

