     // --- вкладки ------------------------------------------------------------

     private fun openTab(id: String) {
         currentTab = id
         browserBar.visibility = if (id == TAB_BROWSER) View.VISIBLE else View.GONE
         for (i in 0 until tabBar.childCount) {
             val button = tabBar.getChildAt(i) as? Button ?: continue
             button.setTextColor(if (button.tag == id) ACCENT else MUTED)
         }
         if (id == TAB_BROWSER) {
             // Мост снимается до загрузки внешней страницы: вкладка браузера
             // открывает чужой интернет, а мост даёт настройки, ключи и
             // распознавание за деньги. Чужая страница их видеть не должна.
             webView.removeJavascriptInterface(BRIDGE_NAME)
             val last = runCatching {
                 JSONObject(bridge.getPrefs("browser")).optString("browser.last")
             }.getOrNull()
             loadAddress(last?.takeIf { it.isNotBlank() } ?: START_PAGE)
         } else {
             webView.addJavascriptInterface(bridge, BRIDGE_NAME)
             webView.loadUrl("${server.baseUrl}/ui/index.html?k=${server.accessToken}&tab=$id")
         }
     }

     /**
      * Перечитать `workspace/web` и перезагрузить страницу. Кнопка в
      * настройках веб-слоя: правка интерфейса не должна требовать перезапуска
      * приложения. Перезагрузка идёт после пересканирования, иначе страница
      * забрала бы ещё старые файлы.
      */
     private fun reloadUi() {
         val tab = currentTab
         web.refreshAsync { changed ->
             postToWeb {
                 if (tab == currentTab && tab != TAB_BROWSER) openTab(tab)
                 if (changed && tab != TAB_BROWSER) tellWeb("'ui:assets-changed'")
             }
         }
     }

     private fun loadAddress(raw: String) {
         val value = raw.trim()
         if (value.isEmpty()) return
         val url = when {
             value.startsWith("http://") || value.startsWith("https://") -> value
             value.contains('.') && !value.contains(' ') -> "https://$value"
             else -> "https://duckduckgo.com/?q=${URLEncoder.encode(value, "UTF-8")}"
         }
         bridge.setPref("browser.last", url)
         webView.loadUrl(url)
     }

