      * иначе падение приходит в фоновый поток и роняет приложение.
      */
     private fun postToWeb(block: () -> Unit) {
         webView.post { runCatching { block() } }
     }

     private fun mimeOf(name: String): String = when (name.substringAfterLast('.', "").lowercase()) {
