         "webp" -> "image/webp"
         "gif" -> "image/gif"
         "avif" -> "image/avif"
         "pdf" -> "application/pdf"
         "txt", "md" -> "text/plain; charset=utf-8"
         else -> "application/octet-stream"
     }

