// Проверка веб-слоя: папка с главами → «Читать» → страницы всех глав подряд.
class Node {
  constructor(tag) {
    this.tag = tag; this.children = []; this.attrs = {}; this.textContent = '';
    this.style = {}; this.className = ''; this.handlers = {};
  }
  appendChild(c) { this.children.push(c); c.parent = this; return c; }
  replaceChildren(...c) { this.children = c; }
  addEventListener(k, v) { this.handlers[k] = v; }
  setAttribute(k, v) { this.attrs[k] = v; }
  querySelectorAll() { return []; }
  scrollIntoView() {}
  get text() { return this.textContent + this.children.map((c) => c.text).join(''); }
}
global.window = {};
global.document = {
  _byId: { view: new Node('main'), title: new Node('strong'), status: new Node('span') },
  getElementById(id) { return this._byId[id] || null; },
  createElement: (t) => new Node(t),
  createTextNode: (t) => { const n = new Node('#text'); n.textContent = t; return n; },
  querySelectorAll: () => [],
};
global.location = { search: '?k=token&tab=library', origin: 'http://127.0.0.1:8080' };

const FOLDER = { uri: 'content://tree/x%2Fdoc%2Ftitle', name: 'Тайтл', dir: true, ext: '', size: 0 };
const PAGES = [
  { name: 'Том 1/001.jpg', uri: 'content://a', entry: '001.jpg', kind: 'zip' },
  { name: 'Том 1/002.jpg', uri: 'content://a', entry: '002.jpg', kind: 'zip' },
  { name: 'Том 2/001.jpg', uri: 'content://b', entry: '001.jpg', kind: 'zip' },
  { name: 'обложка.jpg', uri: 'content://c', kind: 'file' },
];
global.Yomi = { getPrefs: () => '{}', hasApiKey: () => true, setPref: () => {}, appVersion: () => '0.1.0' };
global.fetch = (url) => {
  const u = String(url);
  const body = u.includes('/api/roots') ? [{ uri: 'content://root', name: 'Корень' }]
    : u.includes('/api/list') ? [FOLDER]
      : u.includes('/api/title') ? PAGES : '[]';
  return Promise.resolve({ ok: true, status: 200, text: () => Promise.resolve(JSON.stringify(body)) });
};

