package app.yomikai.shell.library

/**
 * Модель локальной библиотеки: папка — тайтл, тома и страницы внутри.
 *
 * Ни базы, ни кэша метаданных: список строится из того, что отдаёт SAF, и
 * пересобирается при открытии. Тайтл — это папка, том — архив `zip`/`cbz` или
 * отдельная картинка, страница — запись архива.
 */
object Library {

    /** Одна страница: либо запись архива, либо отдельный файл. */
    sealed interface Page {
        val name: String

        /** Запись внутри архива: URI тома плюс имя записи. */
        data class InArchive(
            override val name: String,
            val archiveUri: String,
            val entry: String,
        ) : Page

        /** Отдельный файл-картинка. */
        data class File(
            override val name: String,
            val uri: String,
        ) : Page
    }

    /** Том: архив с главами или одиночная картинка. */
    data class Volume(
        val name: String,
        val uri: String,
        val isArchive: Boolean,
    )

    /** Тайтл: папка со всеми томами и страницами. */
    data class Title(
        val name: String,
        val uri: String,
        val volumes: List<Volume>,
        val pages: List<Page>,
    )

    /**
     * Собрать тайтл из содержимого папки.
     *
     * Порядок глав и страниц — натуральный: «том 2» обязан идти раньше «тома 10»,
     * иначе тайтл читается не по порядку. Архивы и картинки вперемешку не
     * разводим: страницы идут в том порядке, в каком тома стоят в папке.
     */
    fun buildTitle(
        name: String,
        uri: String,
        nodes: List<Node>,
        natural: (String, String) -> Int,
        maxPages: Int,
        entriesOf: (Volume) -> List<String>,
    ): Title {
        val archives = nodes
            .filter { !it.isDirectory && it.extension in ARCHIVE_EXTENSIONS }
            .sortedWith { a, b -> natural(a.name, b.name) }
            .map { Volume(it.name, it.uri, true) }
        val loose = nodes
            .filter { !it.isDirectory && it.extension in IMAGE_EXTENSIONS }
            .sortedWith { a, b -> natural(a.name, b.name) }
            .map { Volume(it.name, it.uri, false) }
        // Подпапки — тоже тома: вложенная «Том 3/» внутри тайтла обязана
        // попасть в чтение, иначе тайтл читается не весь.
        val subdirs = nodes
            .filter { it.isDirectory }
            .sortedWith { a, b -> natural(a.name, b.name) }

        val volumes = ArrayList<Volume>(archives.size + loose.size + subdirs.size)
        val pages = ArrayList<Page>()
        for (volume in archives + loose) {
            if (pages.size >= maxPages) break
            volumes.add(volume)
            if (volume.isArchive) {
                for (entry in entriesOf(volume)) {
                    if (pages.size >= maxPages) break
                    pages.add(Page.InArchive(name = entry.substringAfterLast('/'), archiveUri = volume.uri, entry = entry))
                }
            } else {
                pages.add(Page.File(name = volume.name, uri = volume.uri))
            }
        }
        return Title(name = name, uri = uri, volumes = volumes, pages = pages)
    }

    /** Заголовок каталога: имя папки, в которой могут лежать главы. */
    data class Node(
        val uri: String,
        val name: String,
        val isDirectory: Boolean,
        val size: Long,
        val extension: String,
    ) {
        companion object {
            fun of(uri: String, name: String, isDirectory: Boolean, size: Long): Node = Node(
                uri = uri,
                name = name,
                isDirectory = isDirectory,
                size = size,
                extension = name.substringAfterLast('.', "").lowercase(),
            )
        }
    }

    val IMAGE_EXTENSIONS = setOf("jpg", "jpeg", "png", "webp", "gif", "avif", "jxl")
    val ARCHIVE_EXTENSIONS = setOf("zip", "cbz")
    val BOOK_EXTENSIONS = setOf("pdf", "epub", "fb2", "docx", "txt", "md", "html")
}

package app.yomikai.shell.library

import android.content.Context
import app.yomikai.shell.archive.ZipReader
import app.yomikai.shell.archive.naturalOrder
import app.yomikai.shell.archive.openZip
import app.yomikai.shell.storage.DeviceLibrary
import java.util.Collections
import java.util.concurrent.ConcurrentHashMap

/**
 * Чтение библиотеки с устройства и страниц из архивов.
 *
 * Каталог читается при каждом открытии, поэтому список всегда актуален: файл,
 * добавленный на устройство, виден сразу. Страница достаётся потоком из
 * архива seek'ом по смещению из локального заголовка, в память попадает одна
 * распакованная страница, а не архив целиком.
 */
class TitleRepository(context: Context) {

    private val library = DeviceLibrary(context.applicationContext)

    /** Сколько страниц держим в памяти: текущая и соседние с обеих сторон. */
    private val pageCache = Collections.synchronizedMap(
        object : LinkedHashMap<String, ByteArray>(16, 0.75f, true) {
            override fun removeEldestEntry(eldest: MutableMap.MutableEntry<String, ByteArray>?): Boolean =
                size > CACHE_PAGES
        },
    )

    fun roots(): List<DeviceLibrary.Root> = library.roots()

    fun addRoot(uri: String, name: String) = library.addRoot(uri, name)

    fun removeRoot(uri: String) = library.removeRoot(uri)

    /** Дети каталога как узлы модели. */
    fun list(uri: String): List<Library.Node> = library.list(uri).map { node ->
        Library.Node.of(node.uri, node.name, node.isDirectory, node.size)
    }

    /**
     * Собрать тайтл по папке: её тома плюс страницы из архивов и картинок,
     * включая вложенные папки-тома.
     */
    fun title(folderUri: String, name: String): Library.Title {
        val collected = ArrayList<Library.Node>()
        val entriesByUri = HashMap<String, List<String>>()
        collect(folderUri, collected, entriesByUri, 0)
        return Library.buildTitle(
            name = name,
            uri = folderUri,
            nodes = collected,
            natural = ::naturalOrder,
            maxPages = MAX_PAGES,
            entriesOf = { volume -> entriesByUri[volume.uri].orEmpty() },
        )
    }

    /**
     * Обойти папку тайтла: архивы и картинки берутся из неё самой, из вложенных
     * папок — тоже (вложенная папка это том). Глубина ограничена, иначе
     * циклическое дерево каталогов не закончится никогда.
     */
    private fun collect(
        folderUri: String,
        nodes: MutableList<Library.Node>,
        entriesByUri: MutableMap<String, List<String>>,
        depth: Int,
    ) {
        if (depth > MAX_DEPTH || nodes.size >= MAX_NODES) return
        for (child in list(folderUri)) {
            if (nodes.size >= MAX_NODES) return
            if (child.isDirectory) {
                collect(child.uri, nodes, entriesByUri, depth + 1)
            } else if (child.extension in Library.ARCHIVE_EXTENSIONS) {
                nodes.add(child)
                entriesByUri[child.uri] = runCatching { entries(child.uri) }.getOrDefault(emptyList())
            } else if (child.extension in Library.IMAGE_EXTENSIONS) {
                nodes.add(child)
            }
        }
    }

    /** Записи-картинки архива, в естественном порядке. */
    private fun entries(uri: String): List<String> {
        val (channel, size) = library.openChannel(uri) ?: return emptyList()
        return openZip(channel, size).use { zip ->
            zip.imageEntries(Library.IMAGE_EXTENSIONS).map { it.name }
        }
    }

    /**
     * Байты страницы. Кэш держит несколько страниц вокруг текущей, поэтому
     * листание вперёд-назад не распаковывает архив заново на каждом шаге.
     */
    fun bytes(page: Library.Page): ByteArray? = when (page) {
        is Library.Page.File -> library.readBytes(page.uri)
        is Library.Page.InArchive -> {
            val key = "${page.archiveUri}�${page.entry}"
            pageCache[key] ?: runCatching {
                val (channel, size) = library.openChannel(page.archiveUri) ?: return null
                openZip(channel, size).use { zip ->
                    val entry = zip.find(page.entry) ?: return null
                    zip.read(entry)
                }
            }.getOrNull()?.also { pageCache[key] = it }
        }
    }

    /** Сбросить кэш страниц: память освобождается, список не трогаем. */
    fun clearCache() = pageCache.clear()

    private companion object {
        const val CACHE_PAGES = 6
        const val MAX_PAGES = 5_000
        const val MAX_NODES = 50_000
        const val MAX_DEPTH = 8
    }
}

